const fs = require('fs'), path = require('path')
const files = {}

files["supabase/migrations/007_calendar.sql"] = "-- ============================================================\n-- FYP.STUDIO — Calendario avanzado barbería\n-- Ejecutar DESPUÉS de 005_barbershop.sql\n-- ============================================================\n\n-- Días/horarios bloqueados manualmente por el admin\ncreate table if not exists blocked_slots (\n  id           uuid primary key default uuid_generate_v4(),\n  business_id  uuid not null references businesses(id) on delete cascade,\n  staff_id     uuid references staff(id) on delete cascade,\n  date         date not null,\n  time_slot    text,        -- null = día entero bloqueado\n  reason       text,\n  created_at   timestamptz not null default now()\n);\n\ncreate index if not exists idx_blocked_business on blocked_slots(business_id, date);\ncreate index if not exists idx_blocked_staff    on blocked_slots(staff_id,    date);\n\nalter table blocked_slots enable row level security;\n\ncreate policy \"comercio gestiona blocked_slots\"\n  on blocked_slots for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\n\ncreate policy \"publico lee blocked_slots\"\n  on blocked_slots for select using (true);\n\n-- Log de emails enviados\ncreate table if not exists email_logs (\n  id          uuid primary key default uuid_generate_v4(),\n  business_id uuid not null references businesses(id) on delete cascade,\n  booking_id  uuid references bookings(id) on delete set null,\n  to_email    text not null,\n  type        text not null,\n  status      text not null default 'sent',\n  created_at  timestamptz not null default now()\n);\n\nalter table email_logs enable row level security;\ncreate policy \"comercio ve email_logs\"\n  on email_logs for select\n  using (business_id = get_my_business_id() or is_superadmin());\n\n-- Agregar customer_email a bookings\nalter table bookings\n  add column if not exists customer_email text;\n\n-- Email de notificaciones para la barbería\nalter table businesses\n  add column if not exists notification_email text;\n\nalter publication supabase_realtime add table blocked_slots;\n"

files["types/index.ts"] = "export type Plan = 'basic' | 'pro' | 'premium'\nexport type SubscriptionStatus = 'trial' | 'active' | 'past_due' | 'canceled' | 'suspended'\nexport type OrderStatus = 'pending' | 'confirmed' | 'preparing' | 'ready' | 'shipped' | 'delivered' | 'cancelled'\nexport type PaymentStatus = 'unpaid' | 'paid' | 'refunded'\nexport type DeliveryType = 'delivery' | 'pickup'\nexport type UserRole = 'owner' | 'staff' | 'superadmin'\nexport type AIGenerationType = 'product' | 'promo' | 'insights'\n\nexport interface Business {\n  id: string; name: string; slug: string; description?: string | null\n  logo_url?: string | null; banner_url?: string | null; whatsapp?: string | null\n  address?: string | null; currency: string; primary_color: string\n  secondary_color: string; plan: Plan; active: boolean\n  subscription_status: SubscriptionStatus; subscription_expires_at?: string | null\n  instagram?: string | null; facebook?: string | null; tiktok?: string | null\n  website?: string | null; vertical_type?: string | null; enabled_modules?: string[] | null; created_at: string; updated_at: string\n}\n\nexport interface Profile {\n  id: string; user_id: string; business_id: string\n  role: UserRole; created_at: string; business?: Business\n}\n\nexport interface Category {\n  id: string; business_id: string; name: string; slug: string\n  sort_order: number; active: boolean; created_at: string\n}\n\nexport interface Product {\n  id: string; business_id: string; category_id?: string | null\n  name: string; slug: string; description?: string | null; price: number\n  images: string[]; tags: string[]; stock?: number | null; featured: boolean\n  active: boolean; seo_title?: string | null; seo_desc?: string | null\n  created_at: string; updated_at: string; category?: Category | null\n}\n\nexport interface Customer {\n  id: string; business_id: string; name: string; phone?: string | null\n  address?: string | null; email?: string | null; total_orders: number\n  total_spent: number; created_at: string; updated_at: string\n}\n\nexport interface Order {\n  id: string; business_id: string; customer_id?: string | null\n  order_number: number; status: OrderStatus; payment_status: PaymentStatus\n  confirmed_sale: boolean; delivery_type: DeliveryType; subtotal: number\n  total: number; comment?: string | null; customer_name: string\n  customer_phone?: string | null; customer_address?: string | null\n  created_at: string; updated_at: string; items?: OrderItem[]; customer?: Customer | null\n}\n\nexport interface OrderItem {\n  id: string; order_id: string; product_id?: string | null\n  product_name: string; unit_price: number; quantity: number; subtotal: number\n  product?: Product | null\n}\n\nexport interface CartItem { product: Product; quantity: number }\n\nexport interface CheckoutFormData {\n  name: string; phone: string; address?: string\n  delivery_type: DeliveryType; comment?: string\n}\n\nexport interface CreateOrderResponse { orderId: string; orderNumber: number }\n\nexport interface AIProductOutput {\n  name: string; description: string; category: string; tags: string[]\n  instagram_copy: string; whatsapp_copy: string; hashtags: string[]\n  seo_title: string; seo_description: string\n}\n\nexport interface AIPromoOutput {\n  title: string; body: string; instagram_story: string\n  whatsapp_message: string; cta: string\n}\n\nexport interface DashboardStats {\n  pendingOrders: number; confirmedOrders: number; totalRevenue: number\n  todayRevenue: number; totalProducts: number; totalCustomers: number\n  recentOrders: Order[]; topProducts: { name: string; count: number; revenue: number }[]\n  cancelRate?: number\n}\n\n// ── Inventario ────────────────────────────────────────────────\n\nexport interface InventoryCategory {\n  id: string\n  business_id: string\n  name: string\n  color: string\n  icon: string\n  created_at: string\n}\n\nexport type MovementType = 'entrada' | 'salida' | 'ajuste' | 'devolucion'\n\nexport interface InventoryItem {\n  id: string\n  business_id: string\n  category_id?: string | null\n  product_id?: string | null\n  name: string\n  sku?: string | null\n  unit: string\n  stock_current: number\n  stock_min: number\n  stock_max?: number | null\n  cost_price?: number | null\n  supplier?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // joins\n  category?: InventoryCategory | null\n  product?: { name: string } | null\n}\n\nexport interface InventoryMovement {\n  id: string\n  business_id: string\n  item_id: string\n  order_id?: string | null\n  type: MovementType\n  quantity: number\n  stock_before: number\n  stock_after: number\n  reason?: string | null\n  created_by?: string | null\n  created_at: string\n  item?: InventoryItem | null\n}\n\nexport type StockStatus = 'ok' | 'low' | 'critical' | 'out'\n\nexport function getStockStatus(item: InventoryItem): StockStatus {\n  if (item.stock_current <= 0) return 'out'\n  if (item.stock_current <= item.stock_min * 0.5) return 'critical'\n  if (item.stock_current <= item.stock_min) return 'low'\n  return 'ok'\n}\n\n// ── Proveedores ───────────────────────────────────────────────\n\nexport interface Supplier {\n  id: string\n  business_id: string\n  name: string\n  contact_name?: string | null\n  phone?: string | null\n  email?: string | null\n  address?: string | null\n  city?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // computed\n  products?: SupplierProduct[]\n}\n\nexport interface SupplierProduct {\n  id: string\n  supplier_id: string\n  business_id: string\n  inventory_item_id?: string | null\n  product_name: string\n  sku_supplier?: string | null\n  unit: string\n  price?: number | null\n  min_order?: number | null\n  lead_days?: number | null\n  notes?: string | null\n  created_at: string\n  updated_at: string\n  // join\n  inventory_item?: { name: string } | null\n}\n\n// ── Barbería / Belleza ────────────────────────────────────────\n\nexport interface Branch {\n  id: string\n  business_id: string\n  name: string\n  address?: string | null\n  phone?: string | null\n  whatsapp?: string | null\n  city?: string | null\n  is_main: boolean\n  active: boolean\n  created_at: string\n}\n\nexport interface Staff {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  name: string\n  role: string\n  bio?: string | null\n  avatar_url?: string | null\n  phone?: string | null\n  color: string\n  active: boolean\n  created_at: string\n  updated_at: string\n  branch?: Branch | null\n}\n\nexport interface StaffSchedule {\n  id: string\n  staff_id: string\n  business_id: string\n  day_of_week: number  // 0=Dom, 1=Lun, 2=Mar...\n  start_time: string   // '09:00'\n  end_time: string     // '18:00'\n  break_start?: string | null\n  break_end?: string | null\n  is_working: boolean\n}\n\nexport type BookingStatus = 'pending' | 'confirmed' | 'done' | 'cancelled' | 'noshow'\n\nexport interface Booking {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  staff_id?: string | null\n  product_id?: string | null\n  customer_name: string\n  customer_phone?: string | null\n  customer_email?: string | null\n  date: string         // 'YYYY-MM-DD'\n  start_time: string   // 'HH:MM'\n  end_time: string\n  duration_min: number\n  status: BookingStatus\n  notes?: string | null\n  price?: number | null\n  source: string\n  created_at: string\n  updated_at: string\n  // joins\n  staff?: Staff | null\n  branch?: Branch | null\n  product?: { name: string; price: number } | null\n}\n\n// Page Builder\nexport interface PageConfig {\n  theme: {\n    primaryColor: string\n    secondaryColor: string\n    bgColor: string\n    textColor: string\n    font: string\n    borderRadius: 'none' | 'sm' | 'md' | 'lg' | 'full'\n    style: 'modern' | 'minimal' | 'bold' | 'elegant'\n  }\n  hero: {\n    enabled: boolean\n    title: string\n    subtitle: string\n    ctaText: string\n    ctaAction: 'book' | 'whatsapp' | 'scroll'\n    backgroundType: 'color' | 'image' | 'gradient'\n    backgroundValue: string\n  }\n  sections: PageSection[]\n}\n\nexport interface PageSection {\n  id: string\n  type: 'services' | 'team' | 'gallery' | 'testimonials' | 'contact' | 'hours' | 'promo'\n  enabled: boolean\n  title: string\n  order: number\n}\n\n// ── Gastronomía ───────────────────────────────────────────────\n\nexport interface BusinessHours {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  day_of_week: number\n  is_open: boolean\n  open_time: string\n  close_time: string\n}\n\nexport interface Combo {\n  id: string\n  business_id: string\n  name: string\n  description?: string | null\n  price: number\n  image_url?: string | null\n  active: boolean\n  featured: boolean\n  valid_from?: string | null\n  valid_until?: string | null\n  created_at: string\n  items?: ComboItem[]\n}\n\nexport interface ComboItem {\n  id: string\n  combo_id: string\n  product_id?: string | null\n  product_name: string\n  quantity: number\n}\n\nexport type KitchenStatus = 'pending' | 'confirmed' | 'preparing' | 'ready' | 'shipped' | 'delivered' | 'cancelled'\n\nexport const KITCHEN_FLOW: KitchenStatus[] = [\n  'pending', 'confirmed', 'preparing', 'ready', 'shipped', 'delivered'\n]\n\n// ── Calendario avanzado ───────────────────────────────────────\n\nexport interface BlockedSlot {\n  id: string\n  business_id: string\n  staff_id?: string | null\n  branch_id?: string | null\n  date: string         // 'YYYY-MM-DD'\n  time_slot?: string | null  // null = día completo\n  reason?: string | null\n  created_at: string\n}\n"

files["components/barbershop/BookingFlow.tsx"] = "// components/barbershop/BookingFlow.tsx — Calendario visual verde/rojo\n'use client'\nimport { useState, useMemo, useEffect } from 'react'\nimport { useRouter } from 'next/navigation'\nimport {\n  ChevronRight, ChevronLeft, Check, Loader2,\n  Mail, User, Phone, MapPin, Scissors, Calendar,\n} from 'lucide-react'\nimport { cn, formatPrice } from '@/lib/utils'\nimport type { Business, Staff, Product, Branch } from '@/types'\n\ninterface Props {\n  business: Business\n  staff: (Staff & { schedules?: unknown[] })[]\n  services: Product[]\n  branches: Branch[]\n}\n\nconst MONTHS_ES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio',\n  'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']\nconst DAYS_HEADER = ['L','M','X','J','V','S','D']\nconst DAYS_SHORT  = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']\nconst MONTHS_SHORT = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic']\n\nfunction getSlots(open='09:00', close='19:00', step=30) {\n  const slots: string[] = []\n  const [sh,sm] = open.split(':').map(Number)\n  const [eh,em] = close.split(':').map(Number)\n  let cur = sh*60+sm\n  while (cur < eh*60+em) {\n    slots.push(`${String(Math.floor(cur/60)).padStart(2,'0')}:${String(cur%60).padStart(2,'0')}`)\n    cur += step\n  }\n  return slots\n}\n\nfunction buildCalendar(year: number, month: number) {\n  const firstDay = new Date(year, month, 1).getDay()\n  // Semana empieza lunes: 0=Dom→6, 1=Lun→0 ...\n  const startOffset = firstDay === 0 ? 6 : firstDay - 1\n  const daysInMonth = new Date(year, month+1, 0).getDate()\n  return { startOffset, daysInMonth }\n}\n\nexport default function BookingFlow({ business, staff, services, branches }: Props) {\n  const router = useRouter()\n  const color    = business.primary_color ?? '#1565FF'\n  const currency = business.currency ?? 'UYU'\n\n  const [selectedBranch,  setSelectedBranch]  = useState<Branch|null>(branches[0]??null)\n  const [selectedService, setSelectedService] = useState<Product|null>(services[0]??null)\n  const [selectedStaff,   setSelectedStaff]   = useState<Staff|null>(staff[0]??null)\n  const [selectedDate,    setSelectedDate]    = useState<Date|null>(null)\n  const [selectedTime,    setSelectedTime]    = useState<string|null>(null)\n\n  const today = useMemo(() => { const d=new Date(); d.setHours(0,0,0,0); return d }, [])\n  const [viewYear,  setViewYear]  = useState(today.getFullYear())\n  const [viewMonth, setViewMonth] = useState(today.getMonth())\n\n  // Disponibilidad del mes cargada desde la API\n  const [booked,  setBooked]  = useState<Record<string,string[]>>({})\n  const [blocked, setBlocked] = useState<Record<string,{allDay:boolean;slots:string[];reason?:string}>>({})\n  const [loading, setLoading] = useState(false)\n\n  const ALL_SLOTS = useMemo(() => getSlots('09:00','19:00',30), [])\n\n  useEffect(() => {\n    setLoading(true)\n    const from = `${viewYear}-${String(viewMonth+1).padStart(2,'0')}-01`\n    const lastDay = new Date(viewYear, viewMonth+1, 0).getDate()\n    const to = `${viewYear}-${String(viewMonth+1).padStart(2,'0')}-${lastDay}`\n    const params = new URLSearchParams({ from, to })\n    if (selectedStaff)   params.set('staffId',    selectedStaff.id)\n    if (business.id)     params.set('businessId', business.id)\n\n    fetch(`/api/bookings/availability?${params}`)\n      .then(r=>r.json())\n      .then(d=>{ setBooked(d.booked??{}); setBlocked(d.blocked??{}); setLoading(false) })\n      .catch(()=>setLoading(false))\n  }, [viewYear, viewMonth, selectedStaff, business.id])\n\n  function dateKey(year:number, month:number, day:number) {\n    return `${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`\n  }\n\n  function isDayAvailable(day:number) {\n    const d = new Date(viewYear, viewMonth, day)\n    if (d < today) return false\n    const dk = dateKey(viewYear,viewMonth,day)\n    if (blocked[dk]?.allDay) return false\n    const bookedCount  = booked[dk]?.length ?? 0\n    const blockedCount = blocked[dk]?.slots?.length ?? 0\n    return (bookedCount + blockedCount) < ALL_SLOTS.length\n  }\n\n  function isDayPast(day:number) {\n    return new Date(viewYear,viewMonth,day) < today\n  }\n\n  function isToday(day:number) {\n    return today.getDate()===day && today.getMonth()===viewMonth && today.getFullYear()===viewYear\n  }\n\n  function isSelected(day:number) {\n    return selectedDate?.getDate()===day && selectedDate?.getMonth()===viewMonth && selectedDate?.getFullYear()===viewYear\n  }\n\n  const { startOffset, daysInMonth } = buildCalendar(viewYear, viewMonth)\n\n  // Slots del día seleccionado\n  const selectedDayKey = selectedDate ? dateKey(selectedDate.getFullYear(), selectedDate.getMonth(), selectedDate.getDate()) : null\n  const bookedToday   = selectedDayKey ? (booked[selectedDayKey]  ?? []) : []\n  const blockedToday  = selectedDayKey ? (blocked[selectedDayKey]?.slots ?? []) : []\n  const blockedAllDay = selectedDayKey ? (blocked[selectedDayKey]?.allDay ?? false) : false\n\n  function isSlotAvailable(slot:string) {\n    if (bookedToday.includes(slot))  return false\n    if (blockedToday.includes(slot)) return false\n    // Si el día es hoy, no mostrar slots pasados\n    if (selectedDate && isToday(selectedDate.getDate())) {\n      const now = new Date().toTimeString().slice(0,5)\n      if (slot <= now) return false\n    }\n    return true\n  }\n\n  // Pasos\n  const [step, setStep] = useState<'calendar'|'confirm'>('calendar')\n  const [customerName,  setCustomerName]  = useState('')\n  const [customerPhone, setCustomerPhone] = useState('')\n  const [customerEmail, setCustomerEmail] = useState('')\n  const [notes,         setNotes]         = useState('')\n  const [submitting,    setSubmitting]    = useState(false)\n  const [done,          setDone]          = useState(false)\n  const [error,         setError]         = useState<string|null>(null)\n\n  const duration = 30\n  const endTime = selectedTime ? (() => {\n    const [h,m] = selectedTime.split(':').map(Number)\n    const e = h*60+m+duration\n    return `${String(Math.floor(e/60)).padStart(2,'0')}:${String(e%60).padStart(2,'0')}`\n  })() : ''\n\n  async function handleConfirm(e: React.FormEvent) {\n    e.preventDefault()\n    if (!selectedDate || !selectedTime || !customerName.trim() || !customerPhone.trim()) return\n    if (!customerEmail.trim()) { setError('El email es obligatorio para confirmar el turno'); return }\n    setSubmitting(true); setError(null)\n    try {\n      const dk = dateKey(selectedDate.getFullYear(), selectedDate.getMonth(), selectedDate.getDate())\n      const res = await fetch('/api/bookings', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          businessId:    business.id,\n          branchId:      selectedBranch?.id  ?? null,\n          staffId:       selectedStaff?.id   ?? null,\n          productId:     selectedService?.id ?? null,\n          customerName:  customerName.trim(),\n          customerPhone: customerPhone.trim(),\n          customerEmail: customerEmail.trim(),\n          date:          dk,\n          startTime:     selectedTime,\n          endTime,\n          durationMin:   duration,\n          price:         selectedService?.price ?? null,\n          notes:         notes.trim() || null,\n          source:        'store',\n        }),\n      })\n      const data = await res.json()\n      if (!res.ok) throw new Error(data.error ?? 'Error')\n\n      // Enviar emails de confirmación\n      await fetch('/api/bookings/confirm', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ bookingId: data.bookingId }),\n      })\n\n      setDone(true)\n    } catch(e: unknown) {\n      setError(e instanceof Error ? e.message : 'Error desconocido')\n      setSubmitting(false)\n    }\n  }\n\n  // ── PANTALLA ÉXITO ──\n  if (done) return (\n    <div className=\"min-h-screen flex items-center justify-center p-6 bg-[#F7F9FC]\">\n      <div className=\"text-center max-w-sm w-full animate-fade-in\">\n        <div className=\"h-24 w-24 rounded-full flex items-center justify-center mx-auto mb-6\"\n          style={{ background: `${color}15` }}>\n          <Check size={44} style={{ color }} />\n        </div>\n        <h1 className=\"text-2xl font-black text-gray-900 mb-2\">¡Turno confirmado!</h1>\n        <p className=\"text-gray-500 mb-2\">\n          {selectedDate?.toLocaleDateString('es-UY',{weekday:'long',day:'numeric',month:'long'})} a las {selectedTime}hs\n        </p>\n        <div className=\"bg-white rounded-2xl border border-gray-100 p-4 text-left space-y-2 mb-6 shadow-sm\">\n          {selectedService && <p className=\"text-sm\"><span className=\"text-gray-400\">Servicio:</span> <strong>{selectedService.name}</strong></p>}\n          {selectedStaff   && <p className=\"text-sm\"><span className=\"text-gray-400\">Peluquero:</span> <strong>{selectedStaff.name}</strong></p>}\n          {selectedBranch  && <p className=\"text-sm\"><span className=\"text-gray-400\">Sucursal:</span> <strong>{selectedBranch.name}</strong></p>}\n        </div>\n        <div className=\"rounded-xl bg-blue-50 border border-blue-100 px-4 py-3 mb-5\">\n          <p className=\"text-sm text-blue-800 font-semibold flex items-center gap-2 justify-center\">\n            <Mail size={15}/> Email de confirmación enviado\n          </p>\n          <p className=\"text-xs text-blue-600 mt-0.5\">Revisá tu bandeja de entrada</p>\n        </div>\n        <button onClick={() => router.push(`/store/${business.slug}`)}\n          className=\"w-full rounded-2xl py-3.5 text-sm font-bold text-white\"\n          style={{ background: color }}>\n          Volver a la tienda\n        </button>\n      </div>\n    </div>\n  )\n\n  return (\n    <div className=\"min-h-screen bg-[#F7F9FC]\">\n      {/* Header */}\n      <header className=\"sticky top-0 z-20 bg-white border-b border-gray-100 shadow-sm\">\n        <div className=\"max-w-2xl mx-auto px-4 h-14 flex items-center gap-3\">\n          <button onClick={() => step==='confirm' ? setStep('calendar') : router.back()}\n            className=\"flex h-9 w-9 items-center justify-center rounded-xl text-gray-500 hover:bg-gray-100\">\n            <ChevronLeft size={20}/>\n          </button>\n          <div className=\"flex items-center gap-2.5 flex-1\">\n            {business.logo_url\n              ? <img src={business.logo_url} alt=\"\" className=\"h-8 w-8 rounded-xl object-cover\"/>\n              : <div className=\"h-8 w-8 rounded-xl flex items-center justify-center text-white text-xs font-bold\"\n                  style={{background:color}}>{business.name.slice(0,2).toUpperCase()}</div>\n            }\n            <div>\n              <p className=\"font-bold text-gray-900 text-sm\">{business.name}</p>\n              <p className=\"text-[10px] text-gray-400\">\n                {step==='calendar' ? 'Elegí fecha y hora' : 'Confirmá tu reserva'}\n              </p>\n            </div>\n          </div>\n        </div>\n        {/* Progreso */}\n        <div className=\"h-1 bg-gray-100\">\n          <div className=\"h-full transition-all duration-500\"\n            style={{width:step==='calendar'?'50%':'100%', background:color}}/>\n        </div>\n      </header>\n\n      <div className=\"max-w-2xl mx-auto px-4 py-6 pb-32\">\n\n        {/* ── PASO CALENDAR ── */}\n        {step === 'calendar' && (\n          <div className=\"space-y-5 animate-fade-in\">\n\n            {/* Selectores */}\n            <div className=\"bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden\">\n              {branches.length > 1 && (\n                <StoreSelect label=\"Lugar\" icon={MapPin}\n                  value={selectedBranch?.name ?? ''}\n                  options={branches.map(b=>({id:b.id,label:b.name}))}\n                  onSelect={id=>setSelectedBranch(branches.find(b=>b.id===id)??null)}/>\n              )}\n              {services.length > 0 && (\n                <StoreSelect label=\"Servicio\" icon={Scissors}\n                  value={selectedService?.name ?? ''}\n                  options={services.map(s=>({id:s.id,label:`${s.name}${s.price?` · ${formatPrice(s.price,currency)}`:''}`}))}\n                  onSelect={id=>setSelectedService(services.find(s=>s.id===id)??null)}\n                  hasBorder={branches.length > 1}/>\n              )}\n              {staff.length > 0 && (\n                <StoreSelect label=\"Peluquero\" icon={User}\n                  value={selectedStaff?.name ?? ''}\n                  options={staff.map(s=>({id:s.id,label:s.name}))}\n                  onSelect={id=>setSelectedStaff(staff.find(s=>s.id===id)??null)}\n                  hasBorder={services.length > 0 || branches.length > 1}/>\n              )}\n            </div>\n\n            {/* Calendario */}\n            <div className=\"bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden\">\n              {/* Header del mes */}\n              <div className=\"flex items-center justify-between px-5 py-4 border-b border-gray-100\">\n                <button onClick={() => {\n                  if (viewMonth===0) { setViewYear(y=>y-1); setViewMonth(11) }\n                  else setViewMonth(m=>m-1)\n                  setSelectedDate(null); setSelectedTime(null)\n                }}\n                  className=\"flex h-9 w-9 items-center justify-center rounded-xl text-gray-400\n                             hover:bg-gray-100 transition-colors disabled:opacity-30\"\n                  disabled={viewYear===today.getFullYear()&&viewMonth===today.getMonth()}>\n                  <ChevronLeft size={18}/>\n                </button>\n\n                <p className=\"font-bold text-gray-900 text-base\">\n                  {MONTHS_ES[viewMonth]} {viewYear}\n                </p>\n\n                <button onClick={() => {\n                  if (viewMonth===11) { setViewYear(y=>y+1); setViewMonth(0) }\n                  else setViewMonth(m=>m+1)\n                  setSelectedDate(null); setSelectedTime(null)\n                }}\n                  className=\"flex h-9 w-9 items-center justify-center rounded-xl text-white transition-colors\"\n                  style={{background:color}}>\n                  <ChevronRight size={18}/>\n                </button>\n              </div>\n\n              {/* Días de la semana */}\n              <div className=\"grid grid-cols-7 px-4 py-2\">\n                {DAYS_HEADER.map(d=>(\n                  <div key={d} className=\"text-center text-xs font-bold text-gray-400 py-1\">{d}</div>\n                ))}\n              </div>\n\n              {/* Grid de días */}\n              <div className=\"grid grid-cols-7 gap-1.5 px-4 pb-4\">\n                {/* Offset */}\n                {Array.from({length:startOffset}).map((_,i)=><div key={`e${i}`}/>)}\n\n                {Array.from({length:daysInMonth},(_,i)=>i+1).map(day=>{\n                  const past      = isDayPast(day)\n                  const todayDay  = isToday(day)\n                  const sel       = isSelected(day)\n                  const available = !past && isDayAvailable(day)\n                  const blockedD  = !past && (blocked[dateKey(viewYear,viewMonth,day)]?.allDay ?? false)\n\n                  return (\n                    <button\n                      key={day}\n                      onClick={() => {\n                        if (!available) return\n                        setSelectedDate(new Date(viewYear,viewMonth,day))\n                        setSelectedTime(null)\n                      }}\n                      disabled={!available}\n                      className={cn(\n                        'aspect-square rounded-xl text-sm font-bold transition-all flex items-center justify-center',\n                        'active:scale-95',\n                        past || blockedD\n                          ? 'text-gray-300 cursor-not-allowed'\n                          : sel\n                            ? 'text-white shadow-md ring-2 ring-offset-1'\n                            : available\n                              ? 'text-white hover:opacity-85 cursor-pointer'\n                              : 'text-gray-400 cursor-not-allowed'\n                      )}\n                      style={\n                        sel         ? { background:color, ringColor:color } :\n                        available   ? { background:'#16a34a' } :\n                        blockedD    ? { background:'#fee2e2', color:'#dc2626' } :\n                        past        ? {} :\n                        { background:'#fca5a5', color:'#991b1b' }\n                      }\n                    >\n                      {day}\n                    </button>\n                  )\n                })}\n              </div>\n\n              {/* Leyenda */}\n              <div className=\"flex items-center gap-5 px-5 pb-4 flex-wrap\">\n                <div className=\"flex items-center gap-1.5\">\n                  <div className=\"h-3 w-3 rounded bg-green-600\"/>\n                  <span className=\"text-xs text-gray-500\">Disponible</span>\n                </div>\n                <div className=\"flex items-center gap-1.5\">\n                  <div className=\"h-3 w-3 rounded bg-red-400\"/>\n                  <span className=\"text-xs text-gray-500\">Ocupado / Cerrado</span>\n                </div>\n                <div className=\"flex items-center gap-1.5\">\n                  <div className=\"h-3 w-3 rounded ring-2 ring-offset-1\" style={{background:color, ringColor:color}}/>\n                  <span className=\"text-xs text-gray-500\">Seleccionado</span>\n                </div>\n              </div>\n\n              {/* Slots del día seleccionado */}\n              {selectedDate && !blockedAllDay && (\n                <div className=\"border-t border-gray-100 px-4 pb-5 pt-4\">\n                  <p className=\"text-xs font-bold text-gray-500 uppercase tracking-wide mb-3\">\n                    Horarios disponibles —{' '}\n                    {selectedDate.toLocaleDateString('es-UY',{weekday:'long',day:'numeric',month:'long'})}\n                  </p>\n                  <div className=\"grid grid-cols-4 sm:grid-cols-5 gap-2\">\n                    {ALL_SLOTS.map(slot=>{\n                      const avail = isSlotAvailable(slot)\n                      const sel   = selectedTime === slot\n                      return (\n                        <button key={slot} onClick={()=>avail&&setSelectedTime(slot)}\n                          disabled={!avail}\n                          className={cn(\n                            'py-2.5 rounded-xl text-xs font-bold transition-all border-2',\n                            avail\n                              ? sel\n                                ? 'text-white border-transparent shadow-md'\n                                : 'bg-green-50 text-green-700 border-green-200 hover:bg-green-100'\n                              : 'bg-red-50 text-red-300 border-red-100 cursor-not-allowed line-through'\n                          )}\n                          style={sel?{background:color,borderColor:color}:{}}>\n                          {slot}\n                        </button>\n                      )\n                    })}\n                  </div>\n                </div>\n              )}\n\n              {selectedDate && blockedAllDay && (\n                <div className=\"border-t border-gray-100 px-5 py-4\">\n                  <div className=\"rounded-xl bg-red-50 border border-red-100 px-4 py-3 text-center\">\n                    <p className=\"text-sm font-semibold text-red-700\">\n                      🚫 {blocked[selectedDayKey!]?.reason ?? 'Cerrado este día'}\n                    </p>\n                    <p className=\"text-xs text-red-500 mt-0.5\">Elegí otro día</p>\n                  </div>\n                </div>\n              )}\n            </div>\n\n            {/* Resumen selección */}\n            {selectedDate && selectedTime && (\n              <div className=\"bg-white rounded-2xl border border-gray-100 px-4 py-4 shadow-sm animate-fade-in\">\n                <div className=\"flex items-center justify-between\">\n                  <div>\n                    <p className=\"font-bold text-gray-900 text-sm\">\n                      {selectedDate.toLocaleDateString('es-UY',{weekday:'long',day:'numeric',month:'long'})}\n                    </p>\n                    <p className=\"text-gray-500 text-xs mt-0.5\">\n                      {selectedTime}hs — {endTime}hs\n                      {selectedService && ` · ${selectedService.name}`}\n                    </p>\n                  </div>\n                  {selectedService?.price && (\n                    <p className=\"font-black text-lg\" style={{color}}>\n                      {formatPrice(selectedService.price,currency)}\n                    </p>\n                  )}\n                </div>\n              </div>\n            )}\n          </div>\n        )}\n\n        {/* ── PASO CONFIRMAR ── */}\n        {step === 'confirm' && (\n          <div className=\"space-y-4 animate-fade-in\">\n            {/* Resumen */}\n            <div className=\"bg-white rounded-2xl border border-gray-100 p-5 shadow-sm\">\n              <p className=\"text-xs font-bold text-gray-400 uppercase tracking-wide mb-3\">Resumen</p>\n              <div className=\"space-y-2.5\">\n                {[\n                  ['📅 Fecha', selectedDate?.toLocaleDateString('es-UY',{weekday:'long',day:'numeric',month:'long'})],\n                  ['🕐 Hora',  `${selectedTime}hs — ${endTime}hs`],\n                  selectedService && ['✂️ Servicio', selectedService.name],\n                  selectedStaff   && ['👤 Peluquero', selectedStaff.name],\n                  selectedBranch  && ['📍 Sucursal', selectedBranch.name],\n                  selectedService?.price && ['💰 Precio', formatPrice(selectedService.price,currency)],\n                ].filter(Boolean).map(([k,v])=>(\n                  <div key={k as string} className=\"flex justify-between text-sm\">\n                    <span className=\"text-gray-500\">{k as string}</span>\n                    <span className=\"font-semibold text-gray-900\">{v as string}</span>\n                  </div>\n                ))}\n              </div>\n            </div>\n\n            {/* Formulario */}\n            <div className=\"bg-white rounded-2xl border border-gray-100 p-5 shadow-sm\">\n              <p className=\"text-xs font-bold text-gray-400 uppercase tracking-wide mb-4\">Tus datos</p>\n              <form onSubmit={handleConfirm} className=\"space-y-3\" id=\"confirm-form\">\n                <div>\n                  <label className=\"field-label text-xs\">Nombre <span className=\"text-red-400\">*</span></label>\n                  <input type=\"text\" required value={customerName} onChange={e=>setCustomerName(e.target.value)}\n                    placeholder=\"Tu nombre completo\" className=\"input-base\"/>\n                </div>\n                <div>\n                  <label className=\"field-label text-xs\">Teléfono <span className=\"text-red-400\">*</span></label>\n                  <input type=\"tel\" required value={customerPhone} onChange={e=>setCustomerPhone(e.target.value)}\n                    placeholder=\"099 123 456\" className=\"input-base\" inputMode=\"numeric\"/>\n                </div>\n                <div>\n                  <label className=\"field-label text-xs\">\n                    Email <span className=\"text-red-400\">*</span>\n                    <span className=\"text-gray-400 font-normal ml-1\">— Recibirás la confirmación aquí</span>\n                  </label>\n                  <input type=\"email\" required value={customerEmail} onChange={e=>setCustomerEmail(e.target.value)}\n                    placeholder=\"tu@email.com\" className=\"input-base\"/>\n                </div>\n                <div>\n                  <label className=\"field-label text-xs\">Notas <span className=\"text-gray-400 font-normal\">(opcional)</span></label>\n                  <textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={2}\n                    placeholder=\"Preferencias, aclaraciones...\" className=\"input-base resize-none\"/>\n                </div>\n\n                {error && (\n                  <div className=\"rounded-xl bg-red-50 border border-red-100 px-4 py-3 text-sm text-red-700\">\n                    {error}\n                  </div>\n                )}\n\n                {/* Info email */}\n                <div className=\"rounded-xl bg-blue-50 border border-blue-100 px-4 py-3 flex items-start gap-2.5\">\n                  <Mail size={14} className=\"text-blue-500 shrink-0 mt-0.5\"/>\n                  <div>\n                    <p className=\"text-xs font-semibold text-blue-800\">Confirmación por email</p>\n                    <p className=\"text-[11px] text-blue-600 mt-0.5\">\n                      Recibirás un email con los detalles del turno. La barbería también recibirá una notificación.\n                    </p>\n                  </div>\n                </div>\n              </form>\n            </div>\n          </div>\n        )}\n      </div>\n\n      {/* Botón sticky */}\n      <div className=\"fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-sm border-t border-gray-100 p-4 z-10\">\n        <div className=\"max-w-2xl mx-auto\">\n          {step === 'calendar' ? (\n            <button\n              onClick={() => setStep('confirm')}\n              disabled={!selectedDate || !selectedTime}\n              className=\"w-full flex items-center justify-between rounded-2xl px-6 py-4\n                         text-sm font-bold text-white disabled:opacity-30 transition-all active:scale-[0.98]\"\n              style={{background:color}}>\n              <span>Continuar</span>\n              <div className=\"flex items-center gap-2\">\n                {selectedTime && <span className=\"opacity-80\">{selectedTime}hs</span>}\n                <ChevronRight size={16}/>\n              </div>\n            </button>\n          ) : (\n            <button\n              type=\"submit\"\n              form=\"confirm-form\"\n              disabled={submitting}\n              className=\"w-full flex items-center justify-center gap-3 rounded-2xl py-4\n                         text-sm font-bold text-white disabled:opacity-50 transition-all active:scale-[0.98]\"\n              style={{background:color}}>\n              {submitting ? <Loader2 size={18} className=\"animate-spin\"/> : <Mail size={18}/>}\n              {submitting ? 'Confirmando...' : 'Confirmar y recibir por email'}\n            </button>\n          )}\n          {step === 'confirm' && (\n            <p className=\"text-center text-xs text-gray-400 mt-2\">\n              Recibirás un email de confirmación al instante\n            </p>\n          )}\n        </div>\n      </div>\n    </div>\n  )\n}\n\n// ── Select row ────────────────────────────────────────────────\nfunction StoreSelect({ label, icon: Icon, value, options, onSelect, hasBorder=false }: {\n  label:string; icon:React.ElementType; value:string\n  options:{id:string;label:string}[]; onSelect:(id:string)=>void; hasBorder?:boolean\n}) {\n  return (\n    <div className={cn('flex items-center gap-4 px-5 py-3.5', hasBorder && 'border-t border-gray-100')}>\n      <div className=\"flex items-center gap-2.5 shrink-0 w-24\">\n        <Icon size={14} className=\"text-gray-400 shrink-0\"/>\n        <p className=\"text-sm font-bold text-gray-700\">{label}</p>\n      </div>\n      <select onChange={e=>onSelect(e.target.value)}\n        className=\"flex-1 bg-transparent text-gray-800 text-sm focus:outline-none cursor-pointer\n                   appearance-none font-medium\">\n        {options.map(o=>(\n          <option key={o.id} value={o.id}>{o.label}</option>\n        ))}\n      </select>\n      <ChevronRight size={14} className=\"text-gray-400 shrink-0\"/>\n    </div>\n  )\n}\n"

files["app/admin/barbershop/CalendarDashboard.tsx"] = "// app/admin/barbershop/CalendarDashboard.tsx\n// Calendario de turnos en el admin + gestión de días bloqueados\n'use client'\nimport { useState, useMemo, useEffect } from 'react'\nimport { createClient } from '@/lib/supabase/client'\nimport {\n  ChevronLeft, ChevronRight, Plus, X, Check, Loader2,\n  Lock, Unlock, Clock, User, Scissors, DollarSign,\n  AlertTriangle, Calendar,\n} from 'lucide-react'\nimport { cn, formatPrice } from '@/lib/utils'\nimport type { Booking, Staff, BlockedSlot, BookingStatus } from '@/types'\n\nconst MONTHS_ES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio',\n  'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']\nconst DAYS_HEADER = ['L','M','X','J','V','S','D']\n\nconst STATUS_CFG: Record<BookingStatus,{label:string;bg:string;text:string}> = {\n  pending:   {label:'Pendiente',  bg:'bg-amber-100', text:'text-amber-800'},\n  confirmed: {label:'Confirmado', bg:'bg-blue-100',  text:'text-blue-800'},\n  done:      {label:'Realizado',  bg:'bg-green-100', text:'text-green-800'},\n  cancelled: {label:'Cancelado',  bg:'bg-red-100',   text:'text-red-700'},\n  noshow:    {label:'No asistió', bg:'bg-gray-100',  text:'text-gray-600'},\n}\n\ninterface Props {\n  businessId: string\n  currency: string\n  primaryColor: string\n  staff: Staff[]\n  initialBookings: Booking[]\n  initialBlocked: BlockedSlot[]\n}\n\nfunction buildCalendar(year:number,month:number){\n  const firstDay = new Date(year,month,1).getDay()\n  const startOffset = firstDay===0?6:firstDay-1\n  const daysInMonth = new Date(year,month+1,0).getDate()\n  return {startOffset,daysInMonth}\n}\n\nexport default function CalendarDashboard({\n  businessId, currency, primaryColor, staff,\n  initialBookings, initialBlocked,\n}: Props) {\n  const supabase = createClient()\n  const color = primaryColor\n\n  const today = useMemo(()=>{const d=new Date();d.setHours(0,0,0,0);return d},[])\n  const [viewYear,  setViewYear]  = useState(today.getFullYear())\n  const [viewMonth, setViewMonth] = useState(today.getMonth())\n  const [selectedDay, setSelectedDay] = useState<number|null>(today.getDate())\n\n  const [bookings, setBookings] = useState<Booking[]>(initialBookings)\n  const [blocked,  setBlocked]  = useState<BlockedSlot[]>(initialBlocked)\n  const [updating, setUpdating] = useState<string|null>(null)\n\n  // Modal bloquear día\n  const [showBlockModal, setShowBlockModal] = useState(false)\n  const [blockDate,      setBlockDate]      = useState('')\n  const [blockSlot,      setBlockSlot]      = useState('') // '' = todo el día\n  const [blockReason,    setBlockReason]    = useState('Feriado')\n  const [blockStaff,     setBlockStaff]     = useState('')\n  const [blockLoading,   setBlockLoading]   = useState(false)\n\n  function dateKey(year:number,month:number,day:number){\n    return `${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`\n  }\n\n  // Cargar bookings del mes\n  useEffect(()=>{\n    const from = `${viewYear}-${String(viewMonth+1).padStart(2,'0')}-01`\n    const lastDay = new Date(viewYear,viewMonth+1,0).getDate()\n    const to   = `${viewYear}-${String(viewMonth+1).padStart(2,'0')}-${lastDay}`\n\n    Promise.all([\n      supabase.from('bookings')\n        .select('*, staff:staff(name,color), product:products(name,price)')\n        .eq('business_id',businessId)\n        .gte('date',from).lte('date',to)\n        .not('status','in','(cancelled,noshow)')\n        .order('start_time'),\n      supabase.from('blocked_slots')\n        .select('*').eq('business_id',businessId)\n        .gte('date',from).lte('date',to),\n    ]).then(([b,bl])=>{\n      setBookings(b.data as Booking[] ?? [])\n      setBlocked(bl.data as BlockedSlot[] ?? [])\n    })\n  },[viewYear,viewMonth])\n\n  // Mapa de bookings por día\n  const bookingsByDay = useMemo(()=>{\n    const map: Record<string,Booking[]> = {}\n    bookings.forEach(b=>{ if(!map[b.date])map[b.date]=[]; map[b.date].push(b) })\n    return map\n  },[bookings])\n\n  // Mapa de blocked por día\n  const blockedByDay = useMemo(()=>{\n    const map: Record<string,BlockedSlot[]> = {}\n    blocked.forEach(b=>{ if(!map[b.date])map[b.date]=[]; map[b.date].push(b) })\n    return map\n  },[blocked])\n\n  const {startOffset,daysInMonth} = buildCalendar(viewYear,viewMonth)\n\n  // Turnos del día seleccionado\n  const selectedDayKey = selectedDay ? dateKey(viewYear,viewMonth,selectedDay) : null\n  const dayBookings    = selectedDayKey ? (bookingsByDay[selectedDayKey]??[]).sort((a,b)=>a.start_time.localeCompare(b.start_time)) : []\n  const dayBlocked     = selectedDayKey ? (blockedByDay[selectedDayKey]??[]) : []\n  const dayRevenue     = dayBookings.filter(b=>b.status==='done').reduce((a,b)=>a+(b.price??0),0)\n\n  async function updateStatus(id:string, status:BookingStatus){\n    setUpdating(id)\n    await supabase.from('bookings').update({status}).eq('id',id)\n    setBookings(prev=>prev.map(b=>b.id===id?{...b,status}:b))\n    setUpdating(null)\n  }\n\n  async function addBlock(){\n    if(!blockDate) return\n    setBlockLoading(true)\n    const {data} = await supabase.from('blocked_slots').insert({\n      business_id: businessId,\n      staff_id:    blockStaff||null,\n      date:        blockDate,\n      time_slot:   blockSlot||null,\n      reason:      blockReason||null,\n    }).select('*').single()\n    if(data) setBlocked(prev=>[...prev,data as BlockedSlot])\n    setBlockLoading(false)\n    setShowBlockModal(false)\n    setBlockDate(''); setBlockSlot(''); setBlockReason('Feriado'); setBlockStaff('')\n  }\n\n  async function removeBlock(id:string){\n    await supabase.from('blocked_slots').delete().eq('id',id)\n    setBlocked(prev=>prev.filter(b=>b.id!==id))\n  }\n\n  const dayAllBlocked = dayBlocked.some(b=>!b.time_slot)\n\n  return (\n    <div className=\"space-y-4\">\n      {/* Header */}\n      <div className=\"flex items-center justify-between\">\n        <h2 className=\"text-base font-bold text-gray-900 flex items-center gap-2\">\n          <Calendar size={18} style={{color}}/> Calendario de turnos\n        </h2>\n        <button onClick={()=>setShowBlockModal(true)}\n          className=\"flex items-center gap-2 rounded-xl px-3 py-2 text-xs font-semibold text-white\"\n          style={{background:'#DC2626'}}>\n          <Lock size={12}/> Bloquear día\n        </button>\n      </div>\n\n      {/* Calendario */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden\">\n        {/* Cabecera mes */}\n        <div className=\"flex items-center justify-between px-5 py-3.5 border-b border-gray-100\">\n          <button onClick={()=>{ if(viewMonth===0){setViewYear(y=>y-1);setViewMonth(11)}else setViewMonth(m=>m-1); setSelectedDay(null) }}\n            className=\"flex h-8 w-8 items-center justify-center rounded-xl text-gray-400 hover:bg-gray-100\">\n            <ChevronLeft size={15}/>\n          </button>\n          <p className=\"font-bold text-gray-900 text-sm\">\n            {MONTHS_ES[viewMonth]} {viewYear}\n          </p>\n          <button onClick={()=>{ if(viewMonth===11){setViewYear(y=>y+1);setViewMonth(0)}else setViewMonth(m=>m+1); setSelectedDay(null) }}\n            className=\"flex h-8 w-8 items-center justify-center rounded-xl text-white\"\n            style={{background:color}}>\n            <ChevronRight size={15}/>\n          </button>\n        </div>\n\n        {/* Días semana */}\n        <div className=\"grid grid-cols-7 px-3 py-1.5\">\n          {DAYS_HEADER.map(d=>(\n            <div key={d} className=\"text-center text-[10px] font-bold text-gray-400\">{d}</div>\n          ))}\n        </div>\n\n        {/* Grid */}\n        <div className=\"grid grid-cols-7 gap-1 px-3 pb-3\">\n          {Array.from({length:startOffset}).map((_,i)=><div key={`e${i}`}/>)}\n\n          {Array.from({length:daysInMonth},(_,i)=>i+1).map(day=>{\n            const dk      = dateKey(viewYear,viewMonth,day)\n            const count   = bookingsByDay[dk]?.length ?? 0\n            const blk     = blockedByDay[dk]?.some(b=>!b.time_slot) ?? false\n            const past    = new Date(viewYear,viewMonth,day) < today\n            const isSel   = selectedDay===day\n            const isToday = today.getDate()===day&&today.getMonth()===viewMonth&&today.getFullYear()===viewYear\n\n            return (\n              <button key={day} onClick={()=>setSelectedDay(day)}\n                className={cn(\n                  'relative aspect-square rounded-xl text-xs font-bold transition-all flex flex-col items-center justify-center gap-0.5',\n                  isSel   ? 'text-white ring-2 ring-offset-1' :\n                  blk     ? 'bg-red-100 text-red-700' :\n                  count>0 ? 'text-white' :\n                  past    ? 'text-gray-300' :\n                  isToday ? 'font-black' :\n                  'text-gray-700 hover:bg-gray-50'\n                )}\n                style={\n                  isSel   ? {background:color,ringColor:color} :\n                  count>0 && !blk ? {background:color+'22',color} :\n                  {}\n                }\n              >\n                <span>{day}</span>\n                {count>0 && (\n                  <span className=\"text-[8px] font-bold opacity-80\">{count}</span>\n                )}\n                {blk && <Lock size={8} className=\"opacity-60\"/>}\n              </button>\n            )\n          })}\n        </div>\n\n        {/* Leyenda */}\n        <div className=\"flex items-center gap-4 px-4 pb-3 text-[10px] text-gray-400\">\n          <span className=\"flex items-center gap-1\">\n            <span className=\"h-2.5 w-2.5 rounded\" style={{background:color+'33'}}/> Con turnos\n          </span>\n          <span className=\"flex items-center gap-1\">\n            <span className=\"h-2.5 w-2.5 rounded bg-red-200\"/> Bloqueado\n          </span>\n        </div>\n      </div>\n\n      {/* Detalle del día seleccionado */}\n      {selectedDay && (\n        <div className=\"space-y-3\">\n          <div className=\"flex items-center justify-between\">\n            <p className=\"text-sm font-bold text-gray-900\">\n              {new Date(viewYear,viewMonth,selectedDay).toLocaleDateString('es-UY',{weekday:'long',day:'numeric',month:'long'})}\n            </p>\n            {dayRevenue > 0 && (\n              <p className=\"text-sm font-black\" style={{color}}>\n                {formatPrice(dayRevenue,currency)}\n              </p>\n            )}\n          </div>\n\n          {/* Bloqueados del día */}\n          {dayBlocked.length>0 && (\n            <div className=\"space-y-2\">\n              {dayBlocked.map(bl=>(\n                <div key={bl.id} className=\"flex items-center gap-3 bg-red-50 border border-red-100 rounded-xl px-4 py-2.5\">\n                  <Lock size={13} className=\"text-red-500 shrink-0\"/>\n                  <div className=\"flex-1\">\n                    <p className=\"text-xs font-semibold text-red-700\">\n                      {bl.time_slot ? `${bl.time_slot} bloqueado` : 'Día completo bloqueado'}\n                    </p>\n                    {bl.reason && <p className=\"text-[10px] text-red-500\">{bl.reason}</p>}\n                  </div>\n                  <button onClick={()=>removeBlock(bl.id)}\n                    className=\"flex h-6 w-6 items-center justify-center rounded-lg text-red-400 hover:bg-red-100\">\n                    <X size={12}/>\n                  </button>\n                </div>\n              ))}\n            </div>\n          )}\n\n          {/* Turnos del día */}\n          {dayBookings.length===0 && !dayAllBlocked ? (\n            <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-8 text-center\">\n              <Clock size={20} className=\"mx-auto text-gray-300 mb-2\"/>\n              <p className=\"text-xs text-gray-400\">Sin turnos para este día</p>\n            </div>\n          ) : (\n            <div className=\"space-y-2\">\n              {dayBookings.map(booking=>(\n                <div key={booking.id} className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n                  <div className=\"flex items-start justify-between gap-3 mb-3\">\n                    {/* Hora */}\n                    <div className=\"flex items-center gap-3\">\n                      <div className=\"text-center shrink-0\">\n                        <div className=\"h-10 w-10 rounded-xl flex items-center justify-center text-white text-[11px] font-black\"\n                          style={{background:(booking.staff as {color?:string}|null)?.color??color}}>\n                          {booking.start_time.slice(0,5)}\n                        </div>\n                        <p className=\"text-[9px] text-gray-400 mt-0.5\">{booking.end_time.slice(0,5)}</p>\n                      </div>\n                      <div>\n                        <p className=\"text-sm font-bold text-gray-900\">{booking.customer_name}</p>\n                        {(booking.product as {name?:string}|null)?.name && (\n                          <p className=\"text-xs text-gray-500\">{(booking.product as {name:string}).name}</p>\n                        )}\n                        {(booking.staff as {name?:string}|null)?.name && (\n                          <p className=\"text-xs text-gray-400\">✂️ {(booking.staff as {name:string}).name}</p>\n                        )}\n                        {booking.customer_phone && (\n                          <a href={`tel:${booking.customer_phone}`}\n                            className=\"text-xs text-blue-500\">{booking.customer_phone}</a>\n                        )}\n                      </div>\n                    </div>\n                    <div className=\"text-right shrink-0\">\n                      <span className={cn('badge text-[10px]', STATUS_CFG[booking.status].bg, STATUS_CFG[booking.status].text)}>\n                        {STATUS_CFG[booking.status].label}\n                      </span>\n                      {booking.price!=null && (\n                        <p className=\"text-sm font-black mt-1\" style={{color}}>\n                          {formatPrice(booking.price,currency)}\n                        </p>\n                      )}\n                    </div>\n                  </div>\n\n                  {/* Acciones */}\n                  <div className=\"flex items-center gap-2 flex-wrap\">\n                    {booking.status==='pending' && (\n                      <button onClick={()=>updateStatus(booking.id,'confirmed')}\n                        disabled={updating===booking.id}\n                        className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs font-bold text-white\"\n                        style={{background:color}}>\n                        {updating===booking.id?<Loader2 size={10} className=\"animate-spin\"/>:<Check size={10}/>}\n                        Confirmar\n                      </button>\n                    )}\n                    {(booking.status==='confirmed'||booking.status==='pending') && (\n                      <button onClick={()=>updateStatus(booking.id,'done')}\n                        disabled={updating===booking.id}\n                        className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs font-bold bg-green-500 text-white\">\n                        <Check size={10}/> Realizado\n                      </button>\n                    )}\n                    {!['cancelled','done','noshow'].includes(booking.status) && (\n                      <button onClick={()=>updateStatus(booking.id,'cancelled')}\n                        disabled={updating===booking.id}\n                        className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs text-red-600 bg-red-50\">\n                        <X size={10}/> Cancelar\n                      </button>\n                    )}\n                    {booking.customer_phone && (\n                      <a href={`https://wa.me/${booking.customer_phone.replace(/\\D/g,'')}`} target=\"_blank\"\n                        className=\"flex items-center gap-1 rounded-xl px-3 py-1.5 text-xs font-semibold bg-green-500 text-white\">\n                        WA\n                      </a>\n                    )}\n                  </div>\n\n                  {booking.notes && (\n                    <p className=\"mt-2 text-xs text-amber-700 bg-amber-50 rounded-lg px-2.5 py-1.5\">\n                      💬 {booking.notes}\n                    </p>\n                  )}\n                </div>\n              ))}\n            </div>\n          )}\n        </div>\n      )}\n\n      {/* Modal bloquear */}\n      {showBlockModal && (\n        <div className=\"fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4\">\n          <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={()=>setShowBlockModal(false)}/>\n          <div className=\"relative bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-2xl shadow-2xl\">\n            <div className=\"flex justify-center pt-3 pb-1 sm:hidden\">\n              <div className=\"h-1 w-10 rounded-full bg-gray-200\"/>\n            </div>\n            <div className=\"px-5 py-4 border-b border-gray-100 flex items-center justify-between\">\n              <p className=\"font-bold text-gray-900 flex items-center gap-2\">\n                <Lock size={15} className=\"text-red-500\"/> Bloquear día / horario\n              </p>\n              <button onClick={()=>setShowBlockModal(false)}\n                className=\"h-8 w-8 flex items-center justify-center rounded-xl text-gray-400 hover:bg-gray-100\">\n                <X size={15}/>\n              </button>\n            </div>\n            <div className=\"p-5 space-y-4\">\n              <div>\n                <label className=\"field-label text-xs\">Fecha <span className=\"text-red-400\">*</span></label>\n                <input type=\"date\" value={blockDate} onChange={e=>setBlockDate(e.target.value)}\n                  className=\"input-base\" min={new Date().toISOString().split('T')[0]}/>\n              </div>\n              <div>\n                <label className=\"field-label text-xs\">Horario específico <span className=\"text-gray-400 font-normal\">(vacío = todo el día)</span></label>\n                <input type=\"time\" value={blockSlot} onChange={e=>setBlockSlot(e.target.value)}\n                  className=\"input-base\" placeholder=\"HH:MM\"/>\n              </div>\n              {staff.length>0 && (\n                <div>\n                  <label className=\"field-label text-xs\">Barbero <span className=\"text-gray-400 font-normal\">(vacío = todos)</span></label>\n                  <select value={blockStaff} onChange={e=>setBlockStaff(e.target.value)} className=\"input-base\">\n                    <option value=\"\">Todos los barberos</option>\n                    {staff.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}\n                  </select>\n                </div>\n              )}\n              <div>\n                <label className=\"field-label text-xs\">Motivo</label>\n                <div className=\"flex flex-wrap gap-2 mb-2\">\n                  {['Feriado','Vacaciones','Cerrado','Capacitación','Otro'].map(r=>(\n                    <button key={r} type=\"button\" onClick={()=>setBlockReason(r)}\n                      className={cn('rounded-xl px-3 py-1.5 text-xs font-medium transition-all',\n                        blockReason===r?'text-white':'bg-gray-100 text-gray-600')}>\n                      {blockReason===r?r:r}\n                    </button>\n                  ))}\n                </div>\n                <input type=\"text\" value={blockReason} onChange={e=>setBlockReason(e.target.value)}\n                  placeholder=\"Motivo personalizado\" className=\"input-base text-sm\"/>\n              </div>\n\n              <div className=\"rounded-xl bg-red-50 border border-red-100 px-4 py-3 flex items-start gap-2\">\n                <AlertTriangle size={14} className=\"text-red-500 shrink-0 mt-0.5\"/>\n                <p className=\"text-xs text-red-700\">\n                  Al bloquear este horario, <strong>no se podrá hacer ninguna reserva</strong> desde la tienda pública. Los turnos existentes no se cancelan automáticamente.\n                </p>\n              </div>\n\n              <div className=\"flex gap-3 pb-2\">\n                <button onClick={addBlock} disabled={blockLoading||!blockDate}\n                  className=\"flex-1 flex items-center justify-center gap-2 rounded-xl py-3 text-sm font-bold text-white\n                             disabled:opacity-40 bg-red-600\">\n                  {blockLoading?<Loader2 size={14} className=\"animate-spin\"/>:<Lock size={14}/>}\n                  {blockLoading?'Bloqueando...':'Bloquear'}\n                </button>\n                <button onClick={()=>setShowBlockModal(false)}\n                  className=\"rounded-xl border border-gray-200 px-4 py-3 text-sm font-medium text-gray-600\">\n                  Cancelar\n                </button>\n              </div>\n            </div>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/api/bookings/availability/route.ts"] = "// app/api/bookings/availability/route.ts\nimport { createServiceClient } from '@/lib/supabase/server'\nimport { NextResponse } from 'next/server'\n\nexport async function GET(req: Request) {\n  try {\n    const { searchParams } = new URL(req.url)\n    const staffId    = searchParams.get('staffId')\n    const businessId = searchParams.get('businessId')\n    const from       = searchParams.get('from')\n    const to         = searchParams.get('to')\n\n    if (!from || !to)\n      return NextResponse.json({ booked: {}, blocked: {} })\n\n    const supabase = createServiceClient()\n\n    // 1. Turnos ya reservados\n    let bookingQuery = supabase\n      .from('bookings')\n      .select('date, start_time, status')\n      .gte('date', from)\n      .lte('date', to)\n      .not('status', 'in', '(cancelled,noshow)')\n\n    if (staffId) bookingQuery = bookingQuery.eq('staff_id', staffId)\n    else if (businessId) bookingQuery = bookingQuery.eq('business_id', businessId)\n\n    const { data: bookings } = await bookingQuery\n\n    // 2. Días/slots bloqueados manualmente\n    let blockedQuery = supabase\n      .from('blocked_slots')\n      .select('date, time_slot, reason')\n      .gte('date', from)\n      .lte('date', to)\n\n    if (staffId)    blockedQuery = blockedQuery.or(`staff_id.eq.${staffId},staff_id.is.null`)\n    if (businessId) blockedQuery = blockedQuery.eq('business_id', businessId)\n\n    const { data: blocked } = await blockedQuery\n\n    // Agrupar bookings: { 'YYYY-MM-DD': ['09:00', '09:30'] }\n    const bookedMap: Record<string, string[]> = {}\n    for (const b of bookings ?? []) {\n      if (!bookedMap[b.date]) bookedMap[b.date] = []\n      bookedMap[b.date].push(b.start_time.slice(0, 5))\n    }\n\n    // Agrupar blocked: { 'YYYY-MM-DD': { allDay: bool, slots: ['10:00'] } }\n    const blockedMap: Record<string, { allDay: boolean; slots: string[]; reason?: string }> = {}\n    for (const bl of blocked ?? []) {\n      if (!blockedMap[bl.date]) blockedMap[bl.date] = { allDay: false, slots: [], reason: bl.reason ?? undefined }\n      if (!bl.time_slot) {\n        blockedMap[bl.date].allDay = true\n        blockedMap[bl.date].reason = bl.reason ?? undefined\n      } else {\n        blockedMap[bl.date].slots.push(bl.time_slot)\n      }\n    }\n\n    return NextResponse.json({ booked: bookedMap, blocked: blockedMap })\n  } catch (err) {\n    console.error('[availability]', err)\n    return NextResponse.json({ booked: {}, blocked: {} })\n  }\n}\n"

files["app/api/bookings/confirm/route.ts"] = "// app/api/bookings/confirm/route.ts\n// Envía email de confirmación al cliente y a la barbería\nimport { createServiceClient } from '@/lib/supabase/server'\nimport { NextResponse } from 'next/server'\n\nconst MONTHS_ES = ['enero','febrero','marzo','abril','mayo','junio',\n  'julio','agosto','septiembre','octubre','noviembre','diciembre']\n\nfunction formatDate(dateStr: string) {\n  const [y,m,d] = dateStr.split('-').map(Number)\n  const day = new Date(y,m-1,d)\n  const days = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado']\n  return `${days[day.getDay()]} ${d} de ${MONTHS_ES[m-1]} de ${y}`\n}\n\nasync function sendEmail(to: string, subject: string, html: string) {\n  const apiKey = process.env.RESEND_API_KEY\n  if (!apiKey) {\n    console.log('[email] No RESEND_API_KEY — simulando envío a', to)\n    return true\n  }\n  try {\n    const res = await fetch('https://api.resend.com/emails', {\n      method: 'POST',\n      headers: {\n        'Authorization': `Bearer ${apiKey}`,\n        'Content-Type': 'application/json',\n      },\n      body: JSON.stringify({\n        from:    process.env.EMAIL_FROM ?? 'FyP Studio <noreply@fyp.studio>',\n        to:      [to],\n        subject,\n        html,\n      }),\n    })\n    return res.ok\n  } catch(e) {\n    console.error('[email error]', e)\n    return false\n  }\n}\n\nfunction clientEmailHTML(data: {\n  customerName: string; date: string; time: string; endTime: string\n  service?: string; staff?: string; branch?: string; businessName: string\n  color: string; businessEmail?: string\n}) {\n  return `\n<!DOCTYPE html>\n<html lang=\"es\">\n<head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Turno confirmado</title></head>\n<body style=\"margin:0;padding:0;background:#f4f4f5;font-family:'Inter',Arial,sans-serif;\">\n<div style=\"max-width:520px;margin:32px auto;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);\">\n  <!-- Header -->\n  <div style=\"background:${data.color};padding:32px 32px 24px;text-align:center;\">\n    <div style=\"font-size:36px;margin-bottom:8px;\">✂️</div>\n    <h1 style=\"color:#ffffff;margin:0;font-size:22px;font-weight:800;\">¡Turno confirmado!</h1>\n    <p style=\"color:rgba(255,255,255,0.85);margin:6px 0 0;font-size:14px;\">${data.businessName}</p>\n  </div>\n\n  <!-- Body -->\n  <div style=\"padding:28px 32px;\">\n    <p style=\"color:#374151;font-size:15px;margin:0 0 20px;\">\n      Hola <strong>${data.customerName}</strong>, tu turno está reservado 🎉\n    </p>\n\n    <!-- Detalle -->\n    <div style=\"background:#f9fafb;border-radius:12px;padding:20px;margin-bottom:24px;\">\n      ${[\n        ['📅 Fecha', formatDate(data.date)],\n        ['🕐 Hora', `${data.time} — ${data.endTime} hs`],\n        data.service ? ['✂️ Servicio', data.service] : null,\n        data.staff   ? ['👤 Peluquero', data.staff]   : null,\n        data.branch  ? ['📍 Lugar', data.branch]       : null,\n      ].filter(Boolean).map(([k,v]) => `\n        <div style=\"display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #e5e7eb;\">\n          <span style=\"color:#6b7280;font-size:13px;\">${k}</span>\n          <span style=\"color:#111827;font-size:13px;font-weight:600;\">${v}</span>\n        </div>\n      `).join('')}\n    </div>\n\n    <p style=\"color:#6b7280;font-size:13px;line-height:1.6;margin:0 0 24px;\">\n      Si necesitás cancelar o cambiar el turno, escribinos con anticipación.\n      ${data.businessEmail ? `Podés contactarnos en <a href=\"mailto:${data.businessEmail}\" style=\"color:${data.color};\">${data.businessEmail}</a>` : ''}\n    </p>\n\n    <!-- CTA -->\n    <div style=\"text-align:center;\">\n      <div style=\"display:inline-block;background:${data.color};color:#ffffff;padding:12px 28px;\n                  border-radius:12px;font-size:14px;font-weight:700;\">\n        ¡Nos vemos pronto! 💈\n      </div>\n    </div>\n  </div>\n\n  <!-- Footer -->\n  <div style=\"background:#f9fafb;padding:16px 32px;text-align:center;border-top:1px solid #e5e7eb;\">\n    <p style=\"color:#9ca3af;font-size:12px;margin:0;\">Powered by <strong>FyP Studio</strong></p>\n  </div>\n</div>\n</body></html>`\n}\n\nfunction businessEmailHTML(data: {\n  customerName: string; customerPhone?: string; customerEmail?: string\n  date: string; time: string; endTime: string\n  service?: string; staff?: string; branch?: string\n  notes?: string; businessName: string; color: string; bookingId: string\n}) {\n  return `\n<!DOCTYPE html>\n<html lang=\"es\">\n<head><meta charset=\"UTF-8\"><title>Nuevo turno</title></head>\n<body style=\"margin:0;padding:0;background:#f4f4f5;font-family:'Inter',Arial,sans-serif;\">\n<div style=\"max-width:520px;margin:32px auto;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);\">\n  <div style=\"background:#0B1929;padding:24px 32px;\">\n    <h1 style=\"color:#ffffff;margin:0;font-size:18px;font-weight:800;\">🔔 Nuevo turno reservado</h1>\n    <p style=\"color:rgba(255,255,255,0.6);margin:4px 0 0;font-size:13px;\">${data.businessName}</p>\n  </div>\n  <div style=\"padding:24px 32px;\">\n    <div style=\"background:#f9fafb;border-radius:12px;padding:20px;margin-bottom:20px;\">\n      ${[\n        ['👤 Cliente', data.customerName],\n        data.customerPhone ? ['📱 Teléfono', data.customerPhone] : null,\n        data.customerEmail ? ['📧 Email', data.customerEmail]    : null,\n        ['📅 Fecha', formatDate(data.date)],\n        ['🕐 Hora', `${data.time} — ${data.endTime} hs`],\n        data.service ? ['✂️ Servicio', data.service] : null,\n        data.staff   ? ['👤 Barbero', data.staff]    : null,\n        data.branch  ? ['📍 Sucursal', data.branch]  : null,\n        data.notes   ? ['💬 Notas', data.notes]       : null,\n      ].filter(Boolean).map(([k,v]) => `\n        <div style=\"display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #e5e7eb;\">\n          <span style=\"color:#6b7280;font-size:13px;\">${k}</span>\n          <span style=\"color:#111827;font-size:13px;font-weight:600;\">${v}</span>\n        </div>\n      `).join('')}\n    </div>\n    <p style=\"color:#6b7280;font-size:12px;\">ID del turno: <code>${data.bookingId.slice(0,8)}</code></p>\n  </div>\n</div>\n</body></html>`\n}\n\nexport async function POST(req: Request) {\n  try {\n    const { bookingId } = await req.json()\n    if (!bookingId) return NextResponse.json({ error: 'bookingId requerido' }, { status: 400 })\n\n    const supabase = createServiceClient()\n\n    // Cargar booking completo\n    const { data: booking } = await supabase\n      .from('bookings')\n      .select('*, staff:staff(name), branch:branches(name), product:products(name), business:businesses(name,primary_color,notification_email,whatsapp)')\n      .eq('id', bookingId)\n      .single()\n\n    if (!booking) return NextResponse.json({ error: 'Turno no encontrado' }, { status: 404 })\n\n    const biz   = booking.business as Record<string,unknown>\n    const color = (biz?.primary_color as string) ?? '#1565FF'\n    const bizName = (biz?.name as string) ?? 'Barbería'\n    const bizEmail = (biz?.notification_email as string) ?? ''\n\n    const commonData = {\n      date:     booking.date,\n      time:     booking.start_time.slice(0,5),\n      endTime:  booking.end_time.slice(0,5),\n      service:  (booking.product as {name:string}|null)?.name,\n      staff:    (booking.staff   as {name:string}|null)?.name,\n      branch:   (booking.branch  as {name:string}|null)?.name,\n      businessName: bizName,\n      color,\n    }\n\n    const emails: Promise<boolean>[] = []\n\n    // 1. Email al cliente\n    if (booking.customer_email) {\n      emails.push(sendEmail(\n        booking.customer_email,\n        `✂️ Turno confirmado en ${bizName}`,\n        clientEmailHTML({\n          ...commonData,\n          customerName: booking.customer_name,\n          businessEmail: bizEmail,\n        })\n      ))\n    }\n\n    // 2. Email a la barbería\n    if (bizEmail) {\n      emails.push(sendEmail(\n        bizEmail,\n        `🔔 Nuevo turno — ${booking.customer_name} · ${booking.date} ${booking.start_time.slice(0,5)}`,\n        businessEmailHTML({\n          ...commonData,\n          customerName:  booking.customer_name,\n          customerPhone: booking.customer_phone,\n          customerEmail: booking.customer_email,\n          notes:         booking.notes,\n          bookingId:     booking.id,\n        })\n      ))\n    }\n\n    await Promise.all(emails)\n\n    // Log emails\n    const logEntries = []\n    if (booking.customer_email) {\n      logEntries.push({ business_id: booking.business_id, booking_id: bookingId, to_email: booking.customer_email, type: 'booking_confirm_client', status: 'sent' })\n    }\n    if (bizEmail) {\n      logEntries.push({ business_id: booking.business_id, booking_id: bookingId, to_email: bizEmail, type: 'booking_confirm_business', status: 'sent' })\n    }\n    if (logEntries.length > 0) {\n      await supabase.from('email_logs').insert(logEntries)\n    }\n\n    return NextResponse.json({ ok: true, emailsSent: logEntries.length })\n  } catch (err) {\n    console.error('[booking confirm email]', err)\n    return NextResponse.json({ error: 'Error enviando emails' }, { status: 500 })\n  }\n}\n"

for (const [p,c] of Object.entries(files)) {
  const d = path.dirname(p)
  if (!fs.existsSync(d)) fs.mkdirSync(d,{recursive:true})
  fs.writeFileSync(p,c,'utf8')
  console.log('  OK ' + p)
}
